import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

/* =========================
   FIREBASE (COMENTADO)
   NO SE EJECUTA POR AHORA
========================= */

/*
import {
  createUserWithEmailAndPassword,
  updateProfile,
} from "firebase/auth";

import { auth } from "../../../../firebase/firebaseConfig";

import {
  doc,
  getFirestore,
  setDoc,
} from "firebase/firestore";
*/

const Register = () => {
  /* =========================
     STATES
  ========================= */

  const [name, setName] = useState("");
  const [user, setUser] = useState("");
  const [password, setPassword] = useState("");

  const [error, setError] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");

  const [emailError, setEmailError] = useState("");
  const [passwordError, setPasswordError] = useState("");

  const navigate = useNavigate();

  /* =========================
     REGISTER (SIN FIREBASE)
  ========================= */

  const handleRegister = async () => {
    setError(false);
    setErrorMessage("");

    // Validación campos vacíos
    if (!name || !user || !password) {
      setError(true);
      setErrorMessage("Todos los campos son obligatorios");
      return;
    }

    try {
      /* =========================
         FIREBASE AUTH (DESACTIVADO)
      ========================= */

      /*
      const userCredentials =
        await createUserWithEmailAndPassword(
          auth,
          user,
          password
        );

      const currentUser = userCredentials.user;
      */

      /* =========================
         UPDATE PROFILE (DESACTIVADO)
      ========================= */

      /*
      await updateProfile(currentUser, {
        displayName: name,
      });
      */

      /* =========================
         FIRESTORE (DESACTIVADO)
      ========================= */

      /*
      const db = getFirestore();

      const docRef = doc(
        db,
        "Lists",
        currentUser.email!
      );

      const payload = {
        Movies: [],
      };

      await setDoc(docRef, payload);
      */

      console.log("REGISTRO SIMULADO ✔");

      // Navegación igual funciona
      navigate("/login");

    } catch (error: any) {
      setError(true);
      setErrorMessage(error.message);
    }
  };

  /* =========================
     VALIDACIÓN EMAIL
  ========================= */

  const handleChangeUser = (text: string) => {
    setUser(text);

    const isValid =
      /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text);

    setEmailError(
      isValid ? "" : "Formato de correo inválido"
    );
  };

  /* =========================
     VALIDACIÓN PASSWORD
  ========================= */

  const handleChangePassword = (text: string) => {
    setPassword(text);

    const isValid = text.length >= 6;

    setPasswordError(
      isValid
        ? ""
        : "La contraseña debe contener mínimo 6 caracteres"
    );
  };

  /* =========================
     UI
  ========================= */

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h1 style={styles.title}>Registro</h1>

        {/* NAME */}
        <div style={styles.inputContainer}>
          <input
            type="text"
            placeholder="Nombre"
            value={name}
            onChange={(e) =>
              setName(e.target.value)
            }
            style={styles.input}
          />
        </div>

        {/* EMAIL */}
        <div style={styles.inputContainer}>
          <input
            type="email"
            placeholder="Correo"
            value={user}
            onChange={(e) =>
              handleChangeUser(e.target.value)
            }
            style={styles.input}
          />

          {emailError && (
            <p style={styles.errorText}>
              {emailError}
            </p>
          )}
        </div>

        {/* PASSWORD */}
        <div style={styles.inputContainer}>
          <input
            type="password"
            placeholder="Contraseña"
            value={password}
            onChange={(e) =>
              handleChangePassword(e.target.value)
            }
            style={styles.input}
          />

          {passwordError && (
            <p style={styles.errorText}>
              {passwordError}
            </p>
          )}
        </div>

        {/* ERROR GENERAL */}
        {error && (
          <p style={styles.errorText}>
            {errorMessage}
          </p>
        )}

        {/* BUTTON */}
        <button
          style={styles.button}
          onClick={handleRegister}
        >
          Crear Cuenta
        </button>

        {/* LOGIN */}
        <div style={styles.loginContainer}>
          ¿Ya tienes una cuenta?
          <span
            style={styles.loginText}
            onClick={() =>
              navigate("/login")
            }
          >
            Iniciar sesión
          </span>
        </div>
      </div>
    </div>
  );
};

export default Register;

/* =========================
   STYLES (DARK MODE)
========================= */

const styles: {
  [key: string]: React.CSSProperties;
} = {
  container: {
    width: "100%",
    minHeight: "100vh",
    backgroundColor: "#0a0a0a",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    fontFamily: "Arial, sans-serif",
  },

  card: {
    width: "380px",
    backgroundColor: "#111111",
    border: "1px solid #222",
    borderRadius: "18px",
    padding: "40px",
    display: "flex",
    flexDirection: "column",
    gap: "16px",
    boxShadow:
      "0 0 25px rgba(255,255,255,0.04)",
  },

  title: {
    color: "#ffffff",
    textAlign: "center",
    fontSize: "32px",
    fontWeight: "bold",
    marginBottom: "10px",
  },

  inputContainer: {
    width: "100%",
    display: "flex",
    flexDirection: "column",
    gap: "6px",
  },

  input: {
    width: "100%",
    backgroundColor: "#1a1a1a",
    border: "1px solid #2b2b2b",
    borderRadius: "12px",
    padding: "14px",
    color: "#ffffff",
    fontSize: "14px",
    outline: "none",
  },

  button: {
    width: "100%",
    backgroundColor: "#ffffff",
    color: "#000000",
    border: "none",
    borderRadius: "12px",
    padding: "14px",
    fontSize: "15px",
    fontWeight: "bold",
    cursor: "pointer",
    marginTop: "10px",
  },

  errorText: {
    color: "#9e9e9e",
    fontSize: "13px",
    margin: 0,
  },

  loginContainer: {
    marginTop: "10px",
    textAlign: "center",
    color: "#888",
    fontSize: "14px",
  },

  loginText: {
    color: "#ffffff",
    fontWeight: "bold",
    cursor: "pointer",
    marginLeft: "5px",
  },
};
